`,a.jsx(i.p,{children:"Kadijanci su prihvatili to mišljenje zato što gaje strast prema pretvaranju svakog kur'anskog čuda u snoviđenje, uključujući i kazivanje o Musau, mir neka je na njega, i Hidru, kao i kazivanje o Musaovom štapu i slično. To mišljenje su prihvatili samo da bi odbranili činjenicu da u Mirzinom tobolcu nema nijednog stvarnog dokaza koji bi potkrepio njegove tanke tvrdnje."}),`
