`,a.jsx(i.h2,{children:"Kako kadijanci odgovaraju - primer Meke i Medine"}),`
`,a.jsx(i.p,{children:"Kadijanci, razume se, ta proročanstva ne smatraju neuspelima, pa im menjaju značenje, izvrću ih ili ih proglašavaju metaforičnim."}),`
