`,a.jsx(n,{children:"Umreću ili u Meki ili u Medini."}),`
`,a.jsx(i.p,{children:"Izvor: Tezkira (Tadhkira), str. 591."}),`
`,a.jsx(i.p,{children:"Mirza je umro u Lahoreu, u današnjem Pakistanu, i za čitavog svog života nije kročio ni u Meku ni u Medinu. To očigledno pokazuje da je njegova izjava neistinita, a to je, prema njegovim sopstvenim rečima, najveća sramota od svih sramota."}),`
`,a.jsx(i.p,{children:'Kadijanci to ipak tumače tako da znači da će „umreti pobedom kakva je bila pobeda Meke i Medine", što se iz samog proročanstva nikako ne može zaključiti. Čak i kada bi se takvo tumačenje prihvatilo, Mirzina smrt se ni na koji način ne može nazvati pobedom. U poslednjim trenucima nije bio u stanju da govori niti da komunicira, više puta je gubio svest i na kraju je umro iscrpljen, nakon niza napada proliva u sopstvenoj postelji, kako to potvrđuju kadijanski izvori i svedočanstva očevidaca njegove smrti.'}),`
`,a.jsx(i.h2,{children:"Neoboriv primer neispunjenog proročanstva"}),`
`,a.jsx(i.p,{children:'Postoji, međutim, dovoljno neispunjenih proročanstava koja su neoboriva i oslobođena svakog „metaforičnog tumačenja", bez razumnog i opravdanog odgovora. Prema ranijim izjavama samog Mirze Gulama, potrebno je samo jedno neispunjeno proročanstvo da bi se oborila nečija tvrdnja o poslanstvu.'}),`
`,a.jsx(i.p,{children:"U objavi od 5. novembra 1907. Mirza navodi sledeću objavu koju tvrdi da je primio:"}),`
